package httpapi

import ("crypto/rand"; "encoding/hex"; "encoding/json"; "net/http"; "strings"; "time"; "github.com/Arshak888/Stargate-endpoint-manager/internal/auth"; "github.com/Arshak888/Stargate-endpoint-manager/internal/domain"; "github.com/Arshak888/Stargate-endpoint-manager/internal/store")
type EnrollmentHandler struct { Store *store.MemoryStore }
func randomID() string { b:=make([]byte,16); if _,err:=rand.Read(b); err!=nil { panic(err) }; return hex.EncodeToString(b) }
func (h *EnrollmentHandler) Create(w http.ResponseWriter,r *http.Request) { token,hash,err:=auth.GenerateToken(); if err!=nil { http.Error(w,"token generation failed",500); return }; now:=time.Now().UTC(); e:=domain.Enrollment{ID:randomID(),EndpointID:randomID(),TokenHash:hash,ExpiresAt:now.Add(15*time.Minute),CreatedAt:now}; h.Store.PutEnrollment(e); writeJSON(w,201,map[string]interface{}{"enrollment_id":e.ID,"endpoint_id":e.EndpointID,"token":token,"expires_at":e.ExpiresAt}) }
func (h *EnrollmentHandler) Bootstrap(w http.ResponseWriter,r *http.Request) { var req map[string]interface{}; if json.NewDecoder(r.Body).Decode(&req)!=nil { writeError(w,400,"VALIDATION_FAILED"); return }; id,_:=req["enrollment_id"].(string); token,_:=req["token"].(string); e,ok:=h.Store.GetEnrollment(id); if !ok || e.TokenHash!=auth.HashToken(strings.TrimSpace(token)) { writeError(w,401,"AUTH_INVALID"); return }; consumed,err:=h.Store.ConsumeEnrollment(id,time.Now().UTC()); if err!=nil { writeError(w,401,"ENROLLMENT_EXPIRED"); return }; ep:=domain.Endpoint{ID:consumed.EndpointID,Name:asString(req["name"]),Region:asString(req["region"]),Country:asString(req["country"]),City:asString(req["city"]),Status:domain.EndpointOnline,StargateVersion:asString(req["version"])}; h.Store.PutEndpoint(ep); writeJSON(w,200,map[string]interface{}{"endpoint_id":consumed.EndpointID,"protocol_version":1,"heartbeat_interval_seconds":30}) }
func asString(v interface{}) string { s,_:=v.(string); return s }
